function applyMmToWhite(whiteEl, printTitle, boxWMm, boxHMm) {
    if (!whiteEl) return;
    whiteEl.style.width = whiteWPx + 'px';
    whiteEl.style.height = whiteHPx + 'px';
    whiteEl.style.flex = '0 0 auto';
    whiteEl.style.minWidth = whiteWPx + 'px';
    whiteEl.style.minHeight = whiteHPx + 'px';
    whiteEl.classList.add('barcode-print-area-mm');
    var wMm = boxWMm || whiteWMm;
    var hMm = boxHMm || whiteHMm;
    var sizeLabel = (wMm / 10) + ' cm × ' + (hMm / 10) + ' cm (' + wMm + '×' + hMm + ' mm)';
    whiteEl.setAttribute('title', printTitle || ('Print box ' + sizeLabel));
    var canvasEl = whiteEl.querySelector('.barcode-label-canvas');
    if (canvasEl) {
        canvasEl.style.width = whiteWPx + 'px';
        canvasEl.style.height = whiteHPx + 'px';
        canvasEl.style.minHeight = '0';
    }
    var badge = whiteEl.querySelector('.barcode-print-size-badge');
    if (!badge) {
        badge = document.createElement('span');
        badge.className = 'barcode-print-size-badge';
        whiteEl.appendChild(badge);
    }
    badge.textContent = (wMm / 10) + ' cm × ' + (hMm / 10) + ' cm';
}
if (is120x50Dual) {
    var tagTitle = '120×50 mm sticker · print box 2 cm × 2.5 cm per barcode area.';
    sizeTagBackingBox(barcodeBox, tagTitle);
    if (barcodeBox2) sizeTagBackingBox(barcodeBox2, tagTitle);
    applyMmToWhite(document.getElementById('labelPreview1'), 'Bottom-left print box (2 cm × 2.5 cm)', DUAL_QUADRANT_W_MM, DUAL_QUADRANT_H_MM);
    applyMmToWhite(document.getElementById('labelPreview2'), 'Top-right print box (2 cm × 2.5 cm)', DUAL_QUADRANT_W_MM, DUAL_QUADRANT_H_MM);
